(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["qu"] = {"ui":{"skip":"Ukhuman riy","back":"← AI-gilemanta kutiy","lang.button":"Simi: {name}","lang.dialog":"Simita akllay","lang.search":"Simikunata maskhay","lang.none":"Manan simi tupanchu","lang.notYet":"{name} manaraq t'ikrasqachu","theme.aria":"K'anchaq hinaspa yana rikch'ay t'ikray","theme.toLight":"K'anchaq rikch'aymanmi t'ikray","theme.toDark":"Yana rikch'aymanmi t'ikray","index.title":"AI-gile: AI ruraq aylluyki, huk tablerupi","index.description":"AI-gile kanmi AI programakunata rurayniyuq ayllukunapaq huk kanban tablero. Qan puñunkichu, paykunan llank'ankuku; qanmanmi huk pisi t'inka chayamun: ima akllana, ima yachaykuna, ima chaskina.","hero.logoAlt":"AI-gile tablerupa rikch'ancha","hero.h1.html":"AI ruraq aylluyki, huk&nbsp;tablerupi.","hero.alpha":"🐣 Wichqasqa ñawpaq alfa","hero.alphaTitle":"Ñawpaqmi, mana tukusqachu: ruraykuspa añaychayki!","hero.lede":"Qan puñukuptikim paykuna ruranku. Tutamanta hatarispa huk pisi t'inkata tarinki: wakin tapukuykuna, wakin yachaykunankupaq, huk iskay lila diamantekuna. Ñit'iy, chaskiy, hinaspa mate-tiyaykiman kutiy.","dl.windows":"Windows app","dl.browser":"Navegadorpi ruray","dl.soon":"Usqhayllan hamunqa","dl.notify":"🔔 Kichakuptinqa willaway","dl.notifySmall":"Alfa utaq beta","hero.secondary":"Agile, ichaqa aylluqa mana sayarispa ruraq mate-tiyayta necesitanchu. (Chaywanpas stand-upkunata ruranku.)","pitch.h2":"AI-gile munasqayki simikunapi","pitch.lede":"Huk simimanta 144 kama hatun kayta akllay. Sapa hatun kayqa pachanpaq qillqasqa sapaq willayniyuqmi. Slidertaqa llamiy, utaq flechakunata llamk'apuy.","pitch.rangeLabel":"Simikunapi hatun kay","pitch.dice":"🎲 huk rikch'ay","pitch.words.one":"{n} simi","pitch.words.other":"{n} simikuna","pitch.letters.one":"{n} qillqa","pitch.letters.other":"{n} qillqakuna","pitch.chars.one":"{n} chimpa","pitch.chars.other":"{n} chimpakuna","count.line.html.one":"kunan tablerupi {n} karta kachkan","count.line.html.other":"kunan tablerupi {n} kartakuna kachkan","features.aria":"Imatan ruran","f.pile.h":"Qanpaq huklla t'inka","f.pile.html":"<b>Qanpaq</b>pi tukuy proyectokunamanta qanta suyaqkuna tantasqa kachkan: tapukuykuna, yachaykunanpaq imakuna, runallan ruranan ruraykuna. Colayki niwanmi imataq qatiqnin hinaspa hayk'a pachatan apanqa.","f.sleep.h":"Qan puñukuptiyki llank'aq ayllukuna","f.sleep.p":"Sapa proyectoqa huk pusaqniyuqmi, AI agentekunaq aylluyuqmi. Kartapi rimariy chaymi ayllu rikch'arispa llank'an, hinaspa sayk'usqa runapas qatiy atinan ñampikunawan kutichimun.","f.tester.h":"AI yachaqmi ñawpaqta qhawan","f.tester.p":"Ima qanman chayananpaq, huk yachaqqa app copiapi ñampikunata qatispa imatan rikusqanta rikuchin, captura de pantallawan. Allinta pasaqkunata qhaway hinaspa hukllapi ñit'ispa chaskiy.","f.proof.h":"Rikuchiy, mana simillachu","f.proof.p":"Sapa quykuyqa imataq tikrakusqanta rikuchin: willañiqikuna, diff, capturakuna. Mana sapa appta kichaspa tukusqachu kachkan chaytachu qhawanayki.","f.chat.h":"Pusaqniykikunawan rimay","f.chat.p":"Discord hina huk muyu: sapa proyectopaq huk rikch'ancha, qanta munaqkunapaq lila diamantekuna. Pusaqman yuyayniykita kachay; paymi kartakunaman hinaspa planman tikran, ✅ Go botonwan.","f.tidy.h":"Kikinmi allichakun","f.tidy.p":"Tupaq kartakuna hukman tantakun, chaqruy sutikuna allichasqa, hinaspa token qhawaywanmi programa llamp'u kachkan. Pisi imakunaman tikrayta, pisi yuyaykunatan yuyanayki.","f.private.h":"Qampa, computadorykipi","f.private.li1":"Tableroqa kikiyki machinapin ruwan hinaspa qanlla kutichin.","f.private.li2":"Runakuna chawpipi sapaq DMkunaqa tukuy ladomanta amachasqam.","f.private.li3":"Mana cuentakuna, mana qhatiqkuna, mana cookiekuna.","f.lang.h":"Simiykipi","f.lang.p":"120 simimanta aswan, holandés, galés hinaspa japonesmanta pirata, Yoda hinaspa klingonkama, desarrolladorkunaq simikunapaq inglésman usqhay kutiywan.","tl.aria":"Ñawpaq rimaymanta rurana ñankama pacha tupuy","tl.h2":"Ñawpaq rimaymanta qatiqnin kama","tl.lede":"Chiqap p'unchawkuna hinaspa pachakuna, kikiyki pacha sutipi. Kunanmanta qhepaqa plan, mana p'unchaw rimasqa.","tl.today":"Kunan","tl.planned":"yuyaychasqa","tl.cards.one":"{n} karta","tl.cards.other":"{n} kartakuna","join.h2":"Hukllachakuy","join.lede":"AI-gilemanta huk huch'uy runa hinaspa askha pacienciayuq agentekunan ruranku. Kunanqa sapaqmi, amigokunawan wichqasqa alfapi. Kichakuptin yachaykuyta munankichu?","join.btn":"Munayniyta qillqachiy","join.small":"Correopi qillqasqaykin, manan imatapas","footer.tag":"AI-gile. Mana qhatiqkuna, mana cookiekuna, mana sayarispa mate.","footer.licence":"Negocio licencia","footer.status":"Imayna kasqan","form.sending":"Kachaykuchkan…","form.failed":"Manan allinchu karqan: qhepaman huktawan ruray.","form.offline":"Manan AI-gilemanta chayayta atirqanchu: qhepaman huktawan ruray.","interest.title":"AI-gile: alfa kichakuptin willaway","interest.description":"Correoykita saqiy, AI-gilepa wichqasqa alfan utaq betan kichakuptin yachanaykipaq.","interest.h1":"🔔 Kichakuptinqa willaway","interest.lede":"AI-gileqa wichqasqa ñawpaq alfapin kachkan. Correoykita saqiy, hinaspa qanpaq maya kaptin huk kutilla qillqasaqku.","interest.email":"Correoyki","interest.which":"Mayqin yachay?","interest.alpha":"Wichqasqa alfa: ñawpaq, rakhu, askha tikrakuykunawan","interest.beta":"Beta: aswan takyasqa, qhepaman","interest.both":"Mayqinpas, ñawpaqta chayaqta","interest.submit":"Listaman churaway","interest.thanks":"Añaychayki! Listapin kanki.","licence.title":"AI-gile: negocio licencia","licence.description":"Negocioykipi AI-gilewan llank'ankichu? Mana qullqiyuq negocio licenciata mañakuy.","licence.h1":"📜 Negocio licencia","licence.lede":"Llank'anaykipi AI-gilewan llank'ankichu? Pichus kasqaykita hinaspa imatachus ruranaykita willawayku. Allin ruraq kaptinqa, licenciaqa mana qullqimanta.","licence.company":"Empresa","licence.website":"Web sitio","licence.what":"Imatan ruranki","licence.how":"Kay pachata imaynatan yanapan","licence.email":"Correo","licence.submit":"Mañakuy","licence.thanks":"Añaychayki! Correopi kutichisaqku.","status.title":"AI-gile imayna kasqan","status.h1":"AI-gile imayna kasqan","status.quiet":"Tukuy llamp'u","status.checking":"Qhawachkan…","status.offline":"Kunan manan imayna kasqan serviciuman chayayta atirqanchu (huktawan ruraspa)","status.updated":"{ago} musuqchasqa","status.justNow":"kunallan","status.min":"{n} minuto ñawpaq","status.hours":"{n} ura ñawpaq","status.days":"{n} p'unchaw ñawpaq","live.h2":"Qhaway ruwasqa kachkaqta, kawsaypi","live.caption":"Sapa kartaqa pakasqam: llank'ayninpa rikch'ayninta qhawanki, mana simikunata.","live.watching.one":"kawsaypi: {n} qhawachkan","live.watching.other":"kawsaypi: {n} qhawachkan","live.offline":"Kawsay tablaqa uchuy samarichkan. Chaylla kutimuy.","live.cols":"Backlog|Ruranaykuna|Ruraypi|Ayllu qhawashan|Qanpaq test ruranapaq|Ayllupaq|Tukusqa","live.last.now":"Qhepa carta kunanpuni astasqa","live.last.min.one":"Qhepa carta {n} minutu ñawpaqpi astasqa","live.last.min.other":"Qhepa carta {n} minutu ñawpaqpi astasqa","live.last.hour.one":"Qhepa carta {n} ura ñawpaqpi astasqa","live.last.hour.other":"Qhepa carta {n} ura ñawpaqpi astasqa","live.last.day.one":"Qhepa carta {n} p'unchay ñawpaqpi astasqa","live.last.day.other":"Qhepa carta {n} p'unchay ñawpaqpi astasqa"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotkuna.","Hayñisqa."]},{"n":2,"texts":["Robot kanban.","Agentekuna, allichasqa.","Yuyaykuna, rurasqa."]},{"n":3,"texts":["Robotkunapaq kanban.","Yuyaykuna ruraykunaman tikrakun.","Mana qullqiyuq agente kanban."]},{"n":5,"texts":["Agentekuna pusasqa kanban tablero.","Qan kartata qillqay. Agentekuna ruranku.","Mana qullqiyuq, kayllapi, yachasqa, asikuyniyuq."]},{"n":8,"texts":["Mana qullqiyuq kanban tablero, AI agentekuna chaypi llank'anku.","Yuyayta qillqay. Agentekuna rurankuman. Qan chaskinki.","Huk runapaq hinaspa askha pacienciayuq robotkunapaq agile."]},{"n":13,"texts":["Kikiyki computadorpi kanban tablero kachkan, chaypi AI agentekuna kartakunata hap'ispa sapa p'unchaw llank'anku.","Huk yuyayta qillqay. Agentekunaq huk aylluqa chayta rurankum. Chaymanta huk yachaqqa allinchus qhawanqa.","Mana qullqiyuq, mana cuentayuq, mana qhatiqyuq: huk tablero, wakin robotkuna, hinaspa qan kamachiq kanki."]},{"n":21,"texts":["AI-gile kanmi AI programa agentekunawan llank'ay munaqkunapaq huk kanban tablero. Agentekunam kartakunata hap'inku, qantaq chaykunata yachaykuspa chaskinki.","Sapa proyectoqa huk pusaqniyuqmi, hinaspa AI agentekunaq huk aylluyuqmi. Mayqin kartapipas rimariy, chaymi chay ayllu usqhayllan llank'ayta qallarin.","Kikiyki computadorpi purin kay mana qullqiyuq sapaq ruraykuna tablero. Llank'aqkunaqa robotkunam. Ichaqa arí nispa niqqa, qanmi kanki."]},{"n":34,"texts":["Qan yuyaykunata huk tablerupi churanki. AI agentekunaq aylluqa chay yuyaykunata allinta llank'aq ruraykunaman tikran, yachaykun, hinaspa ruraspa qatinapaq ñampikunawan qanman kutichimun. Qan arí ninaykikama, manan imapas tukusqa nisqachu kanqa.","AI-gile kanmi wasipi ruwasqa kanban tablero, Richmi chayta rurarqan askha yanapayniyuq agentekunawan, kunantaq paykunata kamachin. Mana qullqiyuqmi, kikiyki computadorpi purin, amigokunawanmi rakinakun, manan qhatukunchu. Chayrayku mana ima chanintapas mañakunchu.","Huk simpa kanban tableroyta yuyaykuy, columnakunataq Backlogmanta Tukusqakama kachkan, ichaqa kartakunata AI agentekuna hap'inku. Ñawpaqman rinankuta willanku, wichqasqa kaptinku tapunku, hinaspa sapa kuti qan arí ninaykita suyanku."]},{"n":55,"texts":["AI-gile kanmi huk kanban tablero, chaypi llapa ayllun AI agentekunamanta ruwasqa kachkan. Sapa proyectoqa huk pusaqniyuqmi, paymi llank'ayta yuyaychan, yanapaqninkunataq chayta ruranku. Huk rurayqa wakichisqa kaptin, huk AI yachaqmi chayta yachaykun hinaspa captura de pantallata hap'in, chaymantam qanpa t'inkaykiman chayamun. Chaskiy, utaq rimariy, chaymi paykuna huktawan ruranqaku.","Ñawpaqtaqa huk runaq yuyaynin karqan: askha AI programa llank'aykunata huk pachallapi qatinanpaq. Chaymantam chiqap tablero hinaman wiñarqan. Kikiyki machinapin purin, manan cuentata mañakunchu, manataqmi qhatiqniyuqchu. Amigokunapaq hinaspa yachayta munaqkunapaqmi mana qullqiyuq. Manataqmi tukusqachu, chayraykum rakhu kuskankunata hinaspa wakin kutikuna musphayta suyakuy. Chaymi allin, wakin rimariy qallariypaq.","Chiqaptan rimasun. Yuyaykunaqa qanpam kachkan, rurasqakunatapas qanmi qhawanayki. AI-gile ruran chawpipi tukuy imata: kartakunata allin ñiqinpi tiyachin, rimariykita rikuspa allin agenteta rikch'arichin, imataq tikrakusqanta pacha rikuchin, hinaspa llapa chaykunata qanpaq huk pisi t'inkaman tantan. Chay hinapin qan astawan allin yuyaykunapi kakunki, manataq sapa p'unchaw tukuy ruraykunata qatispa sayk'unkichu, sumaqta samarispa."]},{"n":89,"texts":["AI-gile kanmi mana qullqiyuq kanban tablero, chaytan kikiyki computadorpi purichinki. Runakunaq rantinpi, sapa proyectoqa AI agentekunaq huk aylluyuqmi: huk pusaq yuyaykuykikunata kartakunaman hinaspa planman tikran, yanapaqkunataq kartakunata ñawpaqnin kaqmanta hap'inku. Imapas rurasqa kaptin, huk AI yachaqmi yachay ñampikunata qatin hinaspa imatan rikusqanta qanman rikuchin. Chaymanta Qanpaq sutiyuq huk t'inkapi suyan. Qan chaskinki, utaq rimarinki chaymi ayllu huktawan ruran. Qan mana kaspaqa, imapas manan Tukusqamanqa chayanchu. Chhaynatam qan, mana sayk'uspa, tukuy proyectokunata huk qhawaypi riqsinki.","Wakin ruraykuna mana suyasqayki kanman. Tuta qhawaqqa qan puñuptiyki Ruranaykuna columnata hunt'asqa tiyachin, qanpa kutichiyniykita mana munaq kartakunata akllaspa. Huk token yupaqmi rikuchin agentekuna kunan hinaspa kay semanapi hayk'a llamk'asqankuta, Mana Token Modoqa paykunata qullqi usuchiyta sayachinankupaq niyta. Amigokunaman willayta kachayta atinki, hinaspa sapaq willaykunaqa tukuy ladomanta amachasqam. Tableroqa 120 simipi rimanmi, holandés, flamenco, pirata hinaspa klingonmanta qallarispa. Kaykunamanta mana huk qullqipas yanqachu, manataq pipas qanman chayta rantichiyta munanchu. Chaykunaqa huch'uy yanapaykuna, ichaqa sapa p'unchaw llamk'ayta aswan llamp'u ruranku.","AI-gileqa huch'uy sapaq proyectom, manan empresachu. Richqa wakin AI programa proyectokunata qhawariyta munarqan, ichaqa sapa app kichaspa qhawarinanpaq mana munarqanchu. Chayrayku paypas agentekunapas huk tablerota rurarqaku, chaymantataq chay tablerowan wakin partenta kikin rurarqaku. Kunan wichqasqa ñawpaq alfapi kachkan, chaymi huk chhika amigokunapaq, aswan hukkuna, llank'an. Manan chaninkuna p'anqachu kachkan, manan willakuy t'aqachu, nitaq wiñaypaq planchu. Chay allinpaq rikch'akuptinqa, aswan kichakuptin yachayta mañakuyta atinki. Chaywanpas kusikuspa llank'asqayku, hinaspa amigokunaqa kunanpas sapa p'unchaw yanapawanku."]},{"n":144,"texts":["AI-gile kanmi huk runapaq hinaspa askha AI agentekunapaq kanban tablero. Kikiyki computadorpi purin, hinaspa llapanmi mana qullqimanta. Qan proyectokunata yapanki, sapa proyectotaq huk pusaqta hinaspa huch'uy aylluta chaskin. Pusaqwan Discord hina rimanki, hinaspa huk yuyayta willanki; pusaqmi chayta kartakunaman hinaspa planman tikran, chaymanta qan Go ñit'inaykikama suyan. Ayllu kartakunata allin ñiqinpi llank'an, simi modelokunapaq rurasqa llamp'u comando linewan. Imapas qanman kutimunanpaq, huk AI yachaqmi app copiapi ñampikunata qatin hinaspa captura de pantallata hap'in. Tukusqa llank'ayqa t'inkaykiman chayamun, tikrasqa willañiqikunawan hinaspa diffwan. Qan chaskinki, utaq huk rimariyta saqinki, ayllutaq rikch'arispa huktawan ruran. Qanllan huk kartata Tukusqaman apayta atinki. Chhayna, qan kamachiqmi kanki, agentekunataq paciencianwan qanpa munayniykita huntachinku, mana sayk'uspa, mana qhawarisqa. Manan pipas ruranqachu qanta mana arí nichkaptiyki, nitaq imapas pakallapi ruranqachu.","Huk p'unchaw AI-gilewan, aswan pisi hina. Chisiyaqpi wakin rimariykunata saqinki: kay boton mana allin kankunapi kachkan, chay lista ñiqichasqa kanan, tutayaq modo atikunmanchu. Hinaspa puñuq rinki. Agentekuna rimariykunata ñawinchanku, tikraykunata ruranku, yachaykunku hinaspa qanman kutichimunku. Ruranaykuna chusaqyaptin, tuta qhawaqqa backlogmanta kartakunawan chay columnata hunt'achin, chaykunaqa qanpa kutichiyniykita mana munankuchu. Tutamanta huk pisi t'inka tiyan: wakin tapukuykuna hinaspa wakin yachaykunapaq imakuna, sapankaqa puñuyniyuq runapas qatiy atinan ñampikunayuq hinaspa llank'aqta rikuchiq captura de pantallayuq. Qan ñit'ispa riki, allinkunata chaskinki, wakinkunatataq kutichinki. Huk token yupaqmi rikuchin tukuy chaykuna hayk'a usuchisqanta, Mana Token Modotaq pisi semanakunapaq kachkan. Chaymanta ch'isi mikhunaykita mikhunki, chaypiqa agentekuna manaraq yanapayta atinkuchu. Chhaynapi qan samarispa mikhunki, agentekunataq paykunapa ruraykunata qatispa qanpaq wakichinku, tukuy p'unchaw. Chay hinallatan sapa p'unchaw kutimun.","Ñawpaqta, AI-gile mana ima kasqanta willasqayki. Manan startupchu, manan rantinapaqchu, manataqmi pipas willayniykikunata tantanchu. Mana qullqiyuq tablerom, kikiyki computadorpi purin, mana cuentayuq, mana qhatiqyuq, mana cookieyuq. Ima kasqantaq kay: huk allin ñiqichasqa llaqta, tukuy AI programa proyectokunata huk kutilla rikunaykipaq, chaypi agentekunaq aylluqa kartakunata ruran, qantaq kamachikunki. Tupaq kartakunata huñun, chaqruy sutikunata allichan, hinaspa programa hayk'a llamp'u kasqanta qhawan. Pachaq iskay chunka simita rimanmi, holandés hinaspa flamencomanta pirata hinaspa klingonkama. Amigokunaqa sapa hukninku willayta kachayta atinku, sapaqta hinaspa amachasqa. Richwan hinaspa askha pacienciayuq agentekunawanmi rurasqa, aswan kikinmanta llamk'achispa. Wichqasqa ñawpaq alfapin kachkan, chayrayku wakin kuskankunapi rakhu. Kusiq rikch'akuptinqa, sumaqta mañakuy chaymi ñawpaqmanta yaykunki. Chaymi tukuy kay: huk huch'uy, sumaq, mana qullqiyuq yanapaq, qanpa proyectokunata allinta qhawarinanpaq."]}],"quips":{"1":"Huk simi. Callpasapa. Icha aswan callpasapa.","3":"Kimsa simi. Ñawpaqtan aswan chiqap llapa rantina p'anqakunamanta.","8":"Pusaq simi. Stand-upmantapas aswan pisi.","21":"Hatun kaykunaqa story pointskuna, chaynallatan. Arí, imatan.","55":"Phisqa chunka phisqayuq simi. Ñawinchaspayki iskay karta tukukurqan.","144":"Kayqa hatun kaqmi. 233 manan kanchu. Agentekunan puñuq rirqaku."}},"timeline":{"first-idea.name":"Ñawpaq yuyay","first-idea.line":"Ñawpaqpa ñawpaq rimay, manaraq ima programapas kashaqtin.","first-board.name":"Ñawpaq tablero","first-board.line":"Huk tablero kikin ruraynintan qatispa: kartakuna, columnakuna, llamispa saqiy, proyectokuna.","team-roles.name":"Ayllu hinaspa rolkuna","team-roles.line":"Agentekunap perfilninkuna, ayllu plantillakuna, espaciokuna hinaspa pitaq ima ruran.","install.name":"Churay hinaspa lluqsichiy","install.line":"Huk zip amigo churaykuyta atinan, kikin musuqchakuy, canalkuna hinaspa qhepaman kutiy.","usage-saver.name":"Llamk'ay waqaychay","usage-saver.line":"Ruraykuna hayk'a chanin tupuy, programa llamp'u kachun, ruray kamayki waqaychay.","friends.name":"Amigokuna hinaspa rakinakuy","friends.line":"Sapaq DMkuna, pakasqa relay, qayaykuna, rolkuna hinaspa rakisqa proyectokuna.","languages.name":"Simikuna","languages.line":"Sapa pantalla qillqa huk simi willañiqipi, ñawpaqta holandés hinaspa flamenco.","ai-tester.name":"AI yachaq","ai-tester.line":"Huk yachaqmi sapa quykuyta ñawpaqta qhawan hinaspa imatan rikusqanta rikuchin.","website.name":"Web sitio","website.line":"aigile.lol, ñawpaq rikuchina pacha hinaspa kay pacha tupuy.","streaming.name":"Rimay hinaspa streaming","streaming.line":"Discord, Twitch, OBS, streamer modo, GIFkuna hinaspa emojikuna.","no-ai.name":"Mana AIyuq edicion","no-ai.line":"AI mana kaspa programachaqkunapaq huk tablero, hinaspa llapa runaq tablerukuna.","night-watch.name":"Tuta qhawaq","night-watch.line":"Huk qhawaq hinaspa Scrum Master qan puñuptiyki ayllukunata llank'aypi tiyachin.","p-more.name":"Llapa wakin","p-more.line":"Aswan huch'uy yuyaykuna, kuticha suyaspa.","p-android.name":"Celular hinaspa Android","p-android.line":"Tableruykiman celularmanta chayay, chaymanta kikin Android app.","p-release.name":"Alfa hinaspa aswan","p-release.line":"Wichqasqa alfa, kawsaq web sitio, chaymanta beta.","p-languages.name":"Aswan simikuna","p-languages.line":"Pachaqmanta aswan simikuna, hinaspa yachaqkunapaq ukhu yachay modo.","p-engines.name":"Aswan AI motorkuna","p-engines.line":"Sapa agentepaq Claude, Codex utaq Gemini akllay.","p-pro.name":"Llank'ay yachay","p-pro.line":"Manchay rikch'aykuna, merge punkukuna, pantay kartakuna hinaspa amachaykuna.","p-self.name":"Qanta qhawariy","p-self.line":"Sayk'uy modo, kikiyki qhawarispa yuyarichiykuna hinaspa 4:20.","p-servers.name":"Servidorkuna hinaspa hatun kay","p-servers.line":"Llapa pacha servidor churayniykuna, rolkuna hinaspa wiñayta yuyaychay.","p-livestream.name":"Streaming yapaykuna","p-livestream.line":"Twitch rimay, kikin emojikuna hinaspa llapa runaq kawsaq qhawana."},"words":{"button":"📖 Dev simikuna","h":"📖 Developer simikuna sut'inchasqa","intro":"Developerkuna (hinaspa AI ayllukuna) llamk'achisqan simikuna, llanu simipi.","search":"Simita maskay…","none":"Mana simi tupanchu.","close":"Wichqay","list":[{"id":"backlog","word":"Backlog","text":"Yuyaykuna hinaspa manaraq yuyaychasqa ruranakuna. Chaypi mana imapas ruwakunchu Ruranaykuna kaqman rinankama."},{"id":"sprint","word":"Sprint","text":"Pisi llamk'ay pacha (sapa kuti huk utaq iskay simana) tukunapaq kartakunawan.","also":["sprints"]},{"id":"standup","word":"Stand-up","text":"Pisi tapukuy: sapa ayllu kuska imata rurarqan, imata ruranqa, imataq hark'an.","also":["standup","stand-ups"]},{"id":"bug","word":"Bug","text":"Imachus ruranan hinaqa mana ruraq.","also":["bugs"]},{"id":"test","word":"Test","text":"Tukusqa llamk'ayta pruebay, mañasqa hina ruraptinchus qhawanapaq, chaskinaykiman.","also":["tests"],"noTip":1},{"id":"commit","word":"Commit","text":"Codep waqaychasqa siqin, imachus tikrakurqan pisi willaywan. Sapa kuti chayman kutiyta atinki.","also":["commits"]},{"id":"push","word":"Push","text":"Waqaychasqa siqikunata (commits) kay computadoramanta GitHubman apachiy, backup hinaspa rakisqa kananpaq."},{"id":"branch","word":"Branch","text":"Codepi t'aqa llamk'ay ñan, tikraykuna ruranapaq hatun versionta mana llamiy.","also":["branches"]},{"id":"merge","word":"Merge","text":"Branchpa tikraykunata hatun versionman kutichiy."},{"id":"repo","word":"Repo","text":"Proyectop code folderninpas, commitkunap hunt'a willayninpas, sapa kuti GitHubpi waqaychasqa.","also":["repository"]},{"id":"refactor","word":"Refactor","text":"Codeta allichay, imachus ruranan mana tikraspa: pisi willaq-phirikuna, sut'i sutikuna, pisi kutichay."},{"id":"deploy","word":"Deploy","text":"Musuq versionta kausaypi churay, ej. servidorpi runakuna llamk'achinankupaq."},{"id":"kanban","word":"Kanban","text":"Columnakunayuq tablero (Ruranaykuna, Ruraypi, Tukusqa), chaypi kartakuna ch'ichimanta pañaman llamk'ay kaptin purin."},{"id":"wip","word":"WIP limit","text":"Work in progress: huk columna aswan hayk'a kartakunata hap'inan, ayllu aswan qallariymanta ñawpaqta tukunanpaq.","also":["WIP"]},{"id":"pr","word":"Pull request","text":"Branchpa tikraykunata qhawasqa hinaspa hatun versionman tinkichisqa kananpaq mañakuy.","also":["PR"]},{"id":"hook","word":"Hook","text":"Pisi kamachiy, takyasqa pachapi kikinmanta purin, ej. AI sesión qallarishaqtin, ayllu willaykunata uyarinanpaq.","also":["hooks"]},{"id":"token","word":"Token","text":"AI llamk'achiy yupasqa unidad: ñawinchasqa utaq qillqasqa qillqap pisi killakuna hina. Pisi token, aswan plan qhipan.","also":["tokens"]},{"id":"agent","word":"Agente","text":"Kikin huk rurayta llamk'aq AI: codeta ñawinchan, tikrayta ruran, qhawaykunata purichin, willakun.","also":["agentes"]}]}};
